-- Import des courriers départs 2002-2005
-- Source : depart/2002-2005.xlsx (feuille 2002-2005).
--
-- Comparaison avec les arrivées importées (1995-2005), comme le formulaire :
--   même txt_numTitreFoncier (ou titre mère) et même txt_numLot.
--   « 15/S » et « S 15 » sont le même lot. La date d'arrivée est antérieure ou égale.
--   S'il y a plusieurs courriers pour ce terrain, le plus récent est retenu,
--   de préférence celui qui porte le même nom.
--
-- Cas « Reponse à un Courrier arrivé » ou « Dossier Retourne » (create.vue) :
--   txt_referencecourierarriveecd = txt_reference de l'arrivée, à l'identique.
--   Superficie, lotissement, n° de dossier et nombre de pièces sont repris
--   de l'arrivée quand le classeur départ ne les contient pas.
--   La durée de traitement est calculée comme dans la vue.
--   Elle reste vide si la date d'arrivée n'est que le 1er janvier.
--
-- Cas d'un courrier départ simple : pas de référence d'arrivée.
--   Seules les colonnes du classeur sont enregistrées.
--   La catégorie est déduite du libellé (Demande, Information, Transmission,
--   Signalement, Dossier Retourne). Sinon elle reste vide : l'objet garde le libellé.
--
-- Autres correspondances :
--   N° BE        -> txt_referencecourierdepartcd et le type
--                  BE à réponses Multiples si plusieurs destinataires le même jour
--   DATE DEPART  -> dt_datecouriercd et dt_dateenvoicd
--   PRENOMS+NOM  -> txt_prenomNomcd et txt_destinatairecd
--   DESIGNATION  -> txt_objetcd
--   N° TF / LOT  -> txt_numTitreFonciercd / txt_numLotcd
--   OBSERVATIONS -> txt_observationcd
--   N° d'ordre   -> 4 chiffres par année, comme DepartController::getNextOrdre
--   Référence départ -> <n°>/MFB/DGID/CSF/CSF-NGA/BCAD du jj-mm-aaaa
--
-- Lignes importées : 2792
-- Lignes non importées : 2
--   ligne Excel 2263 : date de départ illisible (vide ; sans nom)
--   ligne Excel 2369 : date de départ illisible (vide ; sans nom)
-- Répartition par année :
--   2002  306
--   2003  609
--   2004  639
--   2005  1238
-- Lien terrain (titre + lot) :
--    1204  réponse reliée à une arrivée
--     849  dont le nom est le même
--     355  même terrain, nom différent
--    1588  courrier départ simple, sans correspondance
--       0  superficies reprises
--       0  lotissements repris
--       0  n° de dossier repris
-- Catégories :
--    1203  Reponse à un Courrier arrivé
--    1005  (sans catégorie)
--     415  Demande
--     127  Transmission de Documents
--      31  Information
--      11  Dossier Retourne
--
-- Types de courrier :
--    2556  BE à réponses Multiples
--     235  BE
--       1  Individuel
--
-- txt_numLotcd est élargi : des lots dépassent 5 caractères.

SET NAMES utf8mb4;

ALTER TABLE `departs`
  MODIFY `txt_numLotcd` VARCHAR(50) NULL,
  MODIFY `txt_numTitreFonciercd` VARCHAR(255) NULL,
  MODIFY `txt_numdossiercd` VARCHAR(50) NULL;

START TRANSACTION;


COMMIT;
